SELECT t.task_id AS taskId, t.node_name AS taskName, t.instance_id AS instanceId, i.process_def_key AS processDefKey, d.process_name AS processDefName, t.assignee AS assigneeId, t.assignee_name AS assigneeName, t.create_time AS createTime, t.due_time AS dueDate, CASE t.priority WHEN 'URGENT' THEN 4 WHEN 'HIGH' THEN 3 WHEN 'NORMAL' THEN 2 WHEN 'LOW' THEN 1 ELSE NULL END AS priority, t.status AS status FROM wf_task t LEFT JOIN wf_process_instance i ON i.instance_id = t.instance_id LEFT JOIN wf_process_definition d ON d.process_def_key = i.process_def_key WHERE t.task_id IN
#{taskId}
ORDER BY t.create_time DESC
